SELECT CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 2 THEN 'mid' ELSE 'low' END quantity_bucket, SUM(unit_price) total_unit_price, SUM(SUM(unit_price)) OVER (ORDER BY CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 2 THEN 'mid' ELSE 'low' END) AS cumulative_unit_price FROM order_items GROUP BY CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 2 THEN 'mid' ELSE 'low' END ORDER BY cumulative_unit_price DESC
